using System;using System.Linq;using System.IO;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEngine.InputSystem;
public sealed class VlabAssetGallery:MonoBehaviour
{
 [SerializeField] GameObject[] prefabs;
 [SerializeField] string[] titles;
 [SerializeField] Camera view;
 GameObject current;Vector3 center;Vector2 scroll;string search="";int index;float radius=.1f,yaw=25,pitch=25,zoom=1;
 public int Count=>prefabs.Length;
 public GameObject Current=>current;
 public bool Select(int i){if(i<0||i>=prefabs.Length||!prefabs[i])return false;if(current){current.SetActive(false);Destroy(current);}index=i;current=Instantiate(prefabs[i]);foreach(var c in current.GetComponentsInChildren<MonoBehaviour>())c.enabled=false;foreach(var b in current.GetComponentsInChildren<Rigidbody>())b.isKinematic=true;var renderers=current.GetComponentsInChildren<Renderer>().Where(r=>r.enabled).ToArray();if(renderers.Length==0){foreach(var r in current.GetComponentsInChildren<MeshRenderer>(true)){r.enabled=true;for(var t=r.transform;t!=null&&t.IsChildOf(current.transform);t=t.parent)t.gameObject.SetActive(true);}renderers=current.GetComponentsInChildren<Renderer>().Where(r=>r.enabled).ToArray();}if(renderers.Length==0)return false;var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);center=bounds.center;radius=Mathf.Max(bounds.extents.magnitude,.001f);yaw=25;pitch=25;zoom=1;Frame();return float.IsFinite(radius);}
 void Start(){Application.targetFrameRate=60;Application.runInBackground=true;Select(0);if(Environment.GetCommandLineArgs().Contains("--vlab-self-test"))StartCoroutine(SelfTest());}
 IEnumerator SelfTest(){var errors=new List<string>();void Log(string text,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)errors.Add(text);}Application.logMessageReceived+=Log;int passed=0;for(int i=0;i<Count;i++){if(Select(i)){bool materials=Current.GetComponentsInChildren<Renderer>().All(r=>r.sharedMaterials.All(m=>m&&m.shader&&m.shader.isSupported&&!m.shader.name.Contains("InternalError")));if(materials)passed++;else errors.Add(titles[i]+": missing/unsupported material");}else errors.Add(titles[i]+": no visible finite geometry");yield return null;}Select(0);yield return new WaitForEndOfFrame();string folder=Path.GetFullPath(Path.Combine(Application.dataPath,".."));string screenshot=Path.Combine(folder,"ViewerPreview.png");ScreenCapture.CaptureScreenshot(screenshot);for(int i=0;i<120&&!File.Exists(screenshot);i++)yield return null;Application.logMessageReceived-=Log;var report=new GalleryReport{status=passed==Count&&errors.Count==0?"PASS":"FAILED",catalog_count=Count,preview_cases_passed=passed,errors=errors.ToArray(),scope="Windows geometry gallery; prefab behaviors disabled for inspection, not a full lesson simulator"};File.WriteAllText(Path.Combine(folder,"ViewerSelfTest.json"),JsonUtility.ToJson(report,true));Application.Quit(report.status=="PASS"?0:1);}
 [Serializable] class GalleryReport{public string status,scope;public int catalog_count,preview_cases_passed;public string[] errors;}
 void Frame(){view.transform.position=center+Quaternion.Euler(pitch,yaw,0)*Vector3.back*radius*3.3f*zoom;view.transform.LookAt(center);view.nearClipPlane=Mathf.Max(.00001f,radius*.001f);view.farClipPlane=Mathf.Max(100,radius*100);view.pixelRect=new Rect(290,0,Mathf.Max(1,Screen.width-290),Screen.height);}
 void Update(){var m=Mouse.current;if(m!=null&&m.position.ReadValue().x>290){if(m.rightButton.isPressed){var d=m.delta.ReadValue();yaw+=d.x*.25f;pitch=Mathf.Clamp(pitch-d.y*.25f,-80,80);}zoom=Mathf.Clamp(zoom*Mathf.Exp(-m.scroll.ReadValue().y*.001f),.25f,5);}Frame();}
 void OnGUI(){GUI.skin.label.wordWrap=true;GUI.skin.label.fontSize=14;GUI.skin.button.fontSize=13;GUI.skin.button.wordWrap=true;GUI.skin.textField.fontSize=15;GUI.Box(new Rect(0,0,280,Screen.height),"");GUI.Label(new Rect(12,12,256,45),"VLAB - THƯ VIỆN MODEL\n"+prefabs.Length+" asset / biến thể trong project");search=GUI.TextField(new Rect(12,64,256,28),search);scroll=GUI.BeginScrollView(new Rect(6,100,268,Mathf.Max(50,Screen.height-220)),scroll,new Rect(0,0,240,prefabs.Length*35));int row=0;for(int i=0;i<prefabs.Length;i++){if(search.Length>0&&titles[i].IndexOf(search,StringComparison.OrdinalIgnoreCase)<0)continue;if(GUI.Button(new Rect(0,row*35,238,32),titles[i]))Select(i);row++;}GUI.EndScrollView();if(GUI.Button(new Rect(12,Screen.height-107,120,30),"Đặt lại góc nhìn")){yaw=25;pitch=25;zoom=1;}if(GUI.Button(new Rect(144,Screen.height-107,124,30),"Thoát"))Application.Quit();GUI.Label(new Rect(12,Screen.height-70,256,65),"Chuột phải: xoay góc nhìn\nCuộn chuột: phóng to/thu nhỏ\nBản xem model; chức năng và scene test có trong project Unity.");}
 // shortcut: geometry preview only; reusable prefab behavior and test scenes are delivered separately.
}
